UPDATE TBL_USER


		USER_PW = #{userPw},


	NAME = #{name},
	JUMIN = #{jumin},
	SCHOOL = #{school},
	GRADE = #{grade}


		, PHONE = #{phone}



		, EMAIL1 = #{email1}



		, EMAIL2 = #{email2}


WHERE USER_ID = #{userId}

mapper.select:

SELECT *
FROM (
	SELECT ROWNUM AS RNUM, B.*
	FROM (
		SELECT USER_ID, USER_PW, NAME, PHONE, EMAIL1, EMAIL2, JUMIN, AUTHORITY, SCHOOL, GRADE, REG_DATE
		FROM TBL_USER
		WHERE 1 = 1





		ORDER BY REG_DATE DESC
	) B
	WHERE ROWNUM <= #{pageEnd}
)
WHERE RNUM >= #{pageStart}

SELECT COUNT(*)
FROM TBL_USER
WHERE USER_ID = #{value}

SELECT T.YEAR AS year, T.TERM AS term
FROM TBL_TEAM_MEMBER TM JOIN TBL_TEAM T ON T.TEAM_NUM = TM.TEAM_NUM
WHERE TM.USER_ID = #{value}
